scripts.k:iso:
mkdir -p iso/boot/grub && cp pizza-os.bin iso/boot/ && echo 'set timeout=0
set default=0
menuentry "pizza-os" {
  multiboot2 /boot/pizza-os.bin
  boot
}' > iso/boot/grub/grub.cfg && grub-mkrescue -o pizza-os.iso iso 2>&1 | tail -3 && mkdir -p public && cp pizza-os.iso public/ && ls -lh pizza-os.iso
